const body = $input.first().json.body || $input.first().json;
const invoiceFiles = body.invoiceFiles || [];
if (!invoiceFiles.length) {
  throw new Error('No invoice files provided in request body');
}
return invoiceFiles.map((file, index) => ({
  json: {
    fileUrl: file.fileUrl || file.url || file,
    fileName: file.fileName || `invoice_${index + 1}`,
    fileIndex: index
  }
}));

// Build Doubao API request body - use getBinaryDataBuffer for correct base64
const items = $input.all();
const apiKey = $env.DOUBAO_API_KEY;
const modelId = $env.DOUBAO_MODEL_ID;
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryKey = Object.keys(item.binary || {})[0];
  if (!binaryKey) throw new Error('No binary data found in downloaded file');
  const binaryData = item.binary[binaryKey];
  const mimeType = binaryData.mimeType || 'application/pdf';
  const fileName = binaryData.fileName || item.json.fileName || 'invoice.pdf';

  // Use n8n helper to get actual binary buffer, then convert to base64
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryKey);
  const base64 = Buffer.from(buffer).toString('base64');
  const dataUri = `data:${mimeType};base64,${base64}`;

  results.push({
    json: {
      apiKey: apiKey,
      model: modelId,
      input: [
        {
          role: 'user',
          content: [
            {
              type: 'input_file',
              file_data: dataUri,
              filename: fileName
            },
            {
              type: 'input_text',
              text: '请识别这张发票/收据中的以下信息，以JSON格式返回：\n1. invoiceType (发票类型：增值税普通发票/增值税专用发票/火车票/机票行程单/出租车发票/酒店住宿发票/餐饮发票/其他)\n2. invoiceNumber (发票号码)\n3. invoiceDate (开票日期，格式YYYY-MM-DD)\n4. amount (金额，数字)\n5. taxAmount (税额，数字，没有则为0)\n6. totalAmount (价税合计/总金额，数字)\n7. sellerName (销售方/收款方名称)\n8. buyerName (购买方/付款方名称)\n9. description (摘要/项目名称)\n\n只返回JSON，不要其他文字。'
            }
          ]
        }
      ]
    }
  });
}
return results;

// Parse LLM response and extract invoice data
const items = $input.all();
const results = [];
for (const item of items) {
  try {
    const response = item.json;
    let text = '';
    if (response.output && Array.isArray(response.output)) {
      for (const out of response.output) {
        if (out.type === 'message' && out.content) {
          for (const c of out.content) {
            if (c.type === 'output_text') text += c.text;
          }
        }
      }
    }
    if (!text && response.choices) {
      text = response.choices[0]?.message?.content || '';
    }
    if (!text) throw new Error('No text in response: ' + JSON.stringify(response).substring(0, 300));
    let jsonStr = text;
    const jsonMatch = text.match(/```json?\s*([\s\S]*?)```/);
    if (jsonMatch) {
      jsonStr = jsonMatch[1].trim();
    } else {
      const braceMatch = text.match(/\{[\s\S]*\}/);
      if (braceMatch) jsonStr = braceMatch[0];
    }
    const invoiceData = JSON.parse(jsonStr);
    results.push({ json: { success: true, data: invoiceData } });
  } catch (e) {
    results.push({ json: { success: false, error: 'Failed to parse LLM response: ' + e.message, raw: item.json } });
  }
}
return results;

// Aggregate all invoice recognition results
const items = $input.all();
const invoices = [];
const errors = [];
for (const item of items) {
  if (item.json.success) {
    invoices.push(item.json.data);
  } else {
    errors.push(item.json.error || 'Unknown error');
  }
}
return [{
  json: {
    success: errors.length === 0,
    invoices: invoices,
    totalCount: items.length,
    successCount: invoices.length,
    errorCount: errors.length,
    errors: errors.length > 0 ? errors : undefined
  }
}];
